import express from "express";
import config from "../config.js";
import { storageDriver } from "../services/storage.service.js";

const mediaRoutes = express.Router();

// Keys are generated by the server (UUID + .mp4); reject anything else.
const KEY_PATTERN = /^[0-9a-f-]{36}\.mp4$/;

mediaRoutes.get("/:key", async (req, res) => {
    if (config.storage.driver !== "s3" || !KEY_PATTERN.test(req.params.key)) {
        return res.status(404).json({ message: "Not found" });
    }
    try {
        const object = await storageDriver.getObject(req.params.key, req.headers.range);
        res.status(req.headers.range ? 206 : 200);
        res.set({
            "Content-Type": object.ContentType || "video/mp4",
            "Accept-Ranges": "bytes",
            "Cache-Control": "public, max-age=86400",
        });
        if (object.ContentLength !== undefined) res.set("Content-Length", String(object.ContentLength));
        if (object.ContentRange) res.set("Content-Range", object.ContentRange);
        // If storage drops mid-stream, abort the response instead of hanging.
        object.Body.on("error", (error) => {
            req.log.error({ key: req.params.key, err: error.message }, "media stream error");
            res.destroy(error);
        });
        object.Body.pipe(res);
    } catch (error) {
        if (error.name === "NoSuchKey" || error.$metadata?.httpStatusCode === 404) {
            return res.status(404).json({ message: "Not found" });
        }
        if (error.$metadata?.httpStatusCode === 416) {
            return res.status(416).end();
        }
        req.log.error({ key: req.params.key, err: error.message }, "media storage error");
        res.status(502).json({ message: "Video storage is unavailable, please try again later" });
    }
});

export default mediaRoutes;
